import { randomInt } from "node:crypto";

export type Participante = {
  nombre: string;
  correo: string;
};

export type Asignacion = {
  de: Participante;
  para: Participante;
};

export type ResultadoValidacion = {
  ok: boolean;
  errores: string[];
};

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Valida la lista de participantes antes del sorteo:
 * - mínimo 2 participantes
 * - nombre no vacío
 * - correo con formato válido
 * - sin correos duplicados (cada participante debe tener su propia casilla)
 */
export function validarParticipantes(
  participantes: Participante[],
): ResultadoValidacion {
  const errores: string[] = [];

  if (participantes.length < 2) {
    errores.push("Se requiere un mínimo de 2 participantes.");
  }

  const correosVistos = new Set<string>();

  participantes.forEach((p, i) => {
    const etiqueta = `Participante ${i + 1}`;
    if (!p.nombre.trim()) {
      errores.push(`${etiqueta}: el nombre no puede estar vacío.`);
    }
    if (!EMAIL_RE.test(p.correo.trim())) {
      errores.push(
        `${etiqueta} (${p.nombre || "sin nombre"}): el correo no es válido.`,
      );
    } else {
      const normalizado = p.correo.trim().toLowerCase();
      if (correosVistos.has(normalizado)) {
        errores.push(
          `${etiqueta}: el correo ${p.correo.trim()} está repetido.`,
        );
      }
      correosVistos.add(normalizado);
    }
  });

  return { ok: errores.length === 0, errores };
}

/**
 * Fisher–Yates criptográficamente aleatorio.
 */
function mezclar<T>(items: T[], aleatorio: (max: number) => number): T[] {
  const copia = [...items];
  for (let i = copia.length - 1; i > 0; i--) {
    const j = aleatorio(i + 1);
    [copia[i], copia[j]] = [copia[j], copia[i]];
  }
  return copia;
}

/**
 * Sortea asignaciones giftor→gifted como un derangement perfecto:
 * - nadie se asigna a sí mismo
 * - cada participante regala exactamente una vez y recibe exactamente una vez
 *
 * Estrategia: mezclar aleatoriamente y reintentar si hay algún punto fijo.
 * Para n ≥ 2 la probabilidad de derangement es ≈ 1/e ≈ 0.368, así que el
 * número esperado de intentos es constante (~e).
 */
export function sortearAmigoSecreto(
  participantes: Participante[],
  aleatorio: (max: number) => number = (max) => randomInt(max),
): Asignacion[] {
  if (participantes.length < 2) {
    throw new Error("Se requiere un mínimo de 2 participantes.");
  }

  // eslint-disable-next-line no-constant-condition
  while (true) {
    const mezclados = mezclar(participantes, aleatorio);

    const hayAutoasignados = participantes.some(
      (p, i) => p.correo.toLowerCase() === mezclados[i].correo.toLowerCase(),
    );
    if (hayAutoasignados) continue;

    return participantes.map((de, i) => ({ de, para: mezclados[i] }));
  }
}

import nodemailer, { type Transporter } from "nodemailer";
import type { Asignacion } from "./sorteo";

export type ConfiguracionSMTP = {
  host: string;
  port: number;
  secure: boolean;
  user?: string;
  pass?: string;
  from: string;
};

export type ResultadoEnvio = {
  entregados: number;
  fallidos: { correo: string; error: string }[];
};

const SMTP_HOST = process.env.SMTP_HOST;
const SMTP_PORT = Number(process.env.SMTP_PORT ?? "587");
const SMTP_USER = process.env.SMTP_USER;
const SMTP_PASS = process.env.SMTP_PASS;
const SMTP_FROM = process.env.SMTP_FROM;

/**
 * Indica si hay configuración SMTP suficiente para enviar correos.
 */
export function smtpConfigurado(): boolean {
  return Boolean(SMTP_HOST && SMTP_FROM);
}

function crearTransporte(config: ConfiguracionSMTP): Transporter {
  return nodemailer.createTransport({
    host: config.host,
    port: config.port,
    secure: config.secure, // true para 465, STARTTLS en 587 va con secure:false
    auth:
      config.user && config.pass
        ? { user: config.user, pass: config.pass }
        : undefined,
  });
}

function cuerpoHtml(asignacion: Asignacion): string {
  return [
    `<!DOCTYPE html>`,
    `<html lang="es">`,
    `<body style="font-family: Arial, Helvetica, sans-serif; color: #171717;">`,
    `  <div style="max-width: 480px; margin: 0 auto; padding: 24px;">`,
    `    <h1 style="font-size: 22px;">🎁 Tu amigo secreto</h1>`,
    `    <p style="font-size: 16px;">Hola ${asignacion.de.nombre},</p>`,
    `    <p style="font-size: 16px;">Esta vez te toca regalarle a:</p>`,
    `    <p style="font-size: 20px; font-weight: bold; background: #f4f4f5; padding: 16px; border-radius: 8px; text-align: center;">`,
    `      ${asignacion.para.nombre}`,
    `    </p>`,
    `    <p style="font-size: 14px; color: #71717a;">`,
    `      Este mensaje contiene solo tu asignación. ¡Guárdatelo bien secreto!`,
    `    </p>`,
    `  </div>`,
    `</body>`,
    `</html>`,
  ].join("\n");
}

function cuerpoTexto(asignacion: Asignacion): string {
  return [
    `Hola ${asignacion.de.nombre},`,
    ``,
    `Esta vez te toca regalarle a: ${asignacion.para.nombre}`,
    ``,
    `Este mensaje contiene solo tu asignación. ¡Guárdatelo bien secreto!`,
  ].join("\n");
}

/**
 * Envía un correo por participante. Cada correo contiene exclusivamente
 * la asignación del participante correspondiente (no se revela el resto).
 */
export async function enviarCorreos(
  asignaciones: Asignacion[],
  config: ConfiguracionSMTP,
): Promise<ResultadoEnvio> {
  const transporte = crearTransporte(config);
  const fallidos: ResultadoEnvio["fallidos"] = [];
  let entregados = 0;

  for (const asignacion of asignaciones) {
    try {
      await transporte.sendMail({
        from: config.from,
        to: asignacion.de.correo,
        subject: "🎁 Tu amigo secreto",
        text: cuerpoTexto(asignacion),
        html: cuerpoHtml(asignacion),
      });
      entregados += 1;
    } catch (error) {
      fallidos.push({
        correo: asignacion.de.correo,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  transporte.close();

  return { entregados, fallidos };
}

export { SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS, SMTP_FROM };

"use server";

import { enviarCorreos, smtpConfigurado, SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS, SMTP_FROM } from "@/lib/mail";
import { sortearAmigoSecreto, validarParticipantes, type Asignacion, type Participante } from "@/lib/sorteo";

export type SorteoRequest = {
  participantes: Participante[];
};

export type SorteoResponse =
  | {
      ok: true;
      entregados: number;
      fallidos: { correo: string; error: string }[];
      asignaciones: Asignacion[];
    }
  | { ok: false; errores: string[] };

export async function realizarSorteo(
  participantes: Participante[],
): Promise<SorteoResponse> {
  // Normalizamos los datos de entrada
  const normalizados = participantes.map((p) => ({
    nombre: p.nombre.trim(),
    correo: p.correo.trim(),
  }));

  const validacion = validarParticipantes(normalizados);
  if (!validacion.ok) {
    return { ok: false, errores: validacion.errores };
  }

  if (!smtpConfigurado()) {
    return {
      ok: false,
      errores: [
        "El servidor SMTP no está configurado. Define SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS y SMTP_FROM en el archivo .env.",
      ],
    };
  }

  const asignaciones = sortearAmigoSecreto(normalizados);

  const resultado = await enviarCorreos(asignaciones, {
    host: SMTP_HOST!,
    port: SMTP_PORT,
    secure: SMTP_PORT === 465,
    user: SMTP_USER,
    pass: SMTP_PASS,
    from: SMTP_FROM!,
  });

  return {
    ok: true,
    entregados: resultado.entregados,
    fallidos: resultado.fallidos,
    asignaciones,
  };
}

"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { realizarSorteo, type SorteoResponse } from "@/app/actions";
import type { Asignacion, Participante } from "@/lib/sorteo";

const STORAGE_KEY = "amigo-secreto-participantes";

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function Organizador() {
  const [participantes, setParticipantes] = useState<Participante[]>([]);
  const [nombre, setNombre] = useState("");
  const [correo, setCorreo] = useState("");
  const [avisoForm, setAvisoForm] = useState<string | null>(null);
  const [avisoLista, setAvisoLista] = useState<string[]>([]);
  const [resultado, setResultado] = useState<SorteoResponse | null>(null);
  const [isPending, startTransition] = useTransition();
  const correoRef = useRef<HTMLInputElement>(null);

  // Persistencia local del navegador (sin base de datos)
  useEffect(() => {
    try {
      const guardado = window.localStorage.getItem(STORAGE_KEY);
      if (guardado) setParticipantes(JSON.parse(guardado));
    } catch {
      // dato corrupto: se empieza de cero
    }
  }, []);

  useEffect(() => {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(participantes));
  }, [participantes]);

  function agregarParticipante(e: React.FormEvent) {
    e.preventDefault();
    const nombreLimpio = nombre.trim();
    const correoLimpio = correo.trim();

    if (!nombreLimpio) {
      setAvisoForm("Escribe el nombre del participante.");
      return;
    }
    if (!EMAIL_RE.test(correoLimpio)) {
      setAvisoForm("Escribe un correo electrónico válido.");
      return;
    }
    if (
      participantes.some(
        (p) => p.correo.toLowerCase() === correoLimpio.toLowerCase(),
      )
    ) {
      setAvisoForm("Ese correo ya está en la lista.");
      return;
    }

    setParticipantes((prev) => [...prev, { nombre: nombreLimpio, correo: correoLimpio }]);
    setAvisoForm(null);
    setResultado(null);
    setNombre("");
    setCorreo("");
    correoRef.current?.focus();
  }

  function quitarParticipante(index: number) {
    setParticipantes((prev) => prev.filter((_, i) => i !== index));
    setResultado(null);
  }

  function sortear() {
    setAvisoLista([]);
    startTransition(async () => {
      const respuesta = await realizarSorteo(participantes);
      if (!respuesta.ok) {
        setAvisoLista(respuesta.errores);
        setResultado(null);
        return;
      }
      setResultado(respuesta);
    });
  }

  return (
    <div className="flex flex-col gap-8">
      {/* Formulario de alta */}
      <form
        onSubmit={agregarParticipante}
        className="grid grid-cols-1 gap-3 sm:grid-cols-[1fr_1fr_auto]"
      >
        <input
          type="text"
          value={nombre}
          onChange={(e) => setNombre(e.target.value)}
          placeholder="Nombre"
          aria-label="Nombre del participante"
          className="h-11 rounded-lg border border-black/[.08] bg-white px-3 text-base outline-none transition-colors placeholder:text-zinc-400 focus:border-black/[.25] dark:border-white/[.145] dark:bg-zinc-900 dark:placeholder:text-zinc-500 dark:focus:border-white/[.35]"
        />
        <input
          ref={correoRef}
          type="email"
          value={correo}
          onChange={(e) => setCorreo(e.target.value)}
          placeholder="Correo electrónico"
          aria-label="Correo electrónico del participante"
          className="h-11 rounded-lg border border-black/[.08] bg-white px-3 text-base outline-none transition-colors placeholder:text-zinc-400 focus:border-black/[.25] dark:border-white/[.145] dark:bg-zinc-900 dark:placeholder:text-zinc-500 dark:focus:border-white/[.35]"
        />
        <button
          type="submit"
          className="h-11 rounded-lg bg-foreground px-5 text-base font-medium text-background transition-colors hover:bg-[#383838] dark:hover:bg-[#ccc]"
        >
          Añadir
        </button>
      </form>

      {avisoForm && (
        <p role="alert" className="text-sm text-red-600 dark:text-red-400">
          {avisoForm}
        </p>
      )}

      {/* Lista de participantes */}
      <section aria-label="Lista de participantes">
        <div className="mb-3 flex items-baseline justify-between">
          <h2 className="text-lg font-semibold">
            Participantes{" "}
            <span className="text-sm font-normal text-zinc-500">
              ({participantes.length})
            </span>
          </h2>
          <span
            className={`text-sm font-medium ${
              participantes.length >= 2
                ? "text-emerald-600 dark:text-emerald-400"
                : "text-amber-600 dark:text-amber-400"
            }`}
          >
            {participantes.length >= 2
              ? "Listo para sortear"
              : "Se requieren al menos 2 participantes"}
          </span>
        </div>

        {participantes.length === 0 ? (
          <p className="rounded-lg border border-dashed border-zinc-300 px-4 py-8 text-center text-sm text-zinc-500 dark:border-zinc-700 dark:text-zinc-400">
            Aún no hay participantes. Añade al menos dos para poder sortear.
          </p>
        ) : (
          <ul className="divide-y divide-black/[.08] rounded-lg border border-black/[.08] dark:divide-white/[.08] dark:border-white/[.145]">
            {participantes.map((p, i) => (
              <li
                key={`${p.correo}-${i}`}
                className="flex items-center justify-between gap-4 px-4 py-3"
              >
                <div className="min-w-0">
                  <p className="truncate font-medium">{p.nombre}</p>
                  <p className="truncate text-sm text-zinc-500 dark:text-zinc-400">
                    {p.correo}
                  </p>
                </div>
                <button
                  type="button"
                  onClick={() => quitarParticipante(i)}
                  aria-label={`Quitar a ${p.nombre}`}
                  className="shrink-0 rounded-md px-2 py-1 text-sm text-zinc-500 transition-colors hover:bg-red-50 hover:text-red-600 dark:text-zinc-400 dark:hover:bg-red-950/40 dark:hover:text-red-400"
                >
                  Quitar
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>

      {/* Acción de sorteo */}
      <div className="flex flex-col gap-3">
        <button
          type="button"
          onClick={sortear}
          disabled={isPending || participantes.length < 2}
          className="h-12 w-full rounded-full bg-foreground text-base font-semibold text-background transition-colors hover:bg-[#383838] disabled:cursor-not-allowed disabled:opacity-40 dark:hover:bg-[#ccc] sm:w-[260px]"
        >
          {isPending ? "Sorteando y enviando…" : "🎉 Realizar sorteo"}
        </button>

        {avisoLista.length > 0 && (
          <ul
            role="alert"
            className="list-inside list-disc rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700 dark:border-red-900 dark:bg-red-950/40 dark:text-red-300"
          >
            {avisoLista.map((e) => (
              <li key={e}>{e}</li>
            ))}
          </ul>
        )}
      </div>

      {/* Resultado del sorteo */}
      {resultado?.ok && (
        <section
          aria-label="Resultado del sorteo"
          className="flex flex-col gap-4 rounded-lg border border-emerald-200 bg-emerald-50 p-5 dark:border-emerald-900 dark:bg-emerald-950/30"
        >
          <h2 className="text-lg font-semibold text-emerald-800 dark:text-emerald-300">
            ¡Sorteo realizado!
          </h2>
          <p className="text-sm text-emerald-800/90 dark:text-emerald-300/90">
            Se enviaron {resultado.entregados} correos, cada uno con la
            asignación exclusiva de su destinatario.
          </p>

          <details className="text-sm">
            <summary className="cursor-pointer select-none font-medium text-emerald-900 dark:text-emerald-200">
              Ver quién le regala a quién (solo para el organizador)
            </summary>
            <ul className="mt-2 divide-y divide-emerald-200/70 dark:divide-emerald-900">
              {resultado.asignaciones.map((a: Asignacion) => (
                <li
                  key={`${a.de.correo}->${a.para.correo}`}
                  className="py-2 text-emerald-900 dark:text-emerald-200"
                >
                  {a.de.nombre} → {a.para.nombre}
                </li>
              ))}
            </ul>
          </details>

          {resultado.fallidos.length > 0 && (
            <div>
              <p className="text-sm font-medium text-amber-700 dark:text-amber-300">
                No se pudo entregar el correo a:
              </p>
              <ul className="mt-1 list-inside list-disc text-sm text-amber-700 dark:text-amber-300">
                {resultado.fallidos.map((f) => (
                  <li key={f.correo}>
                    {f.correo}: {f.error}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </section>
      )}
    </div>
  );
}

import Organizador from "@/app/components/organizador";

export default function Home() {
  return (
    <div className="flex flex-col flex-1 items-center bg-zinc-50 font-sans dark:bg-black">
      <main className="flex w-full max-w-2xl flex-col gap-8 px-6 py-16">
        <header className="flex flex-col gap-2">
          <h1 className="text-3xl font-semibold tracking-tight text-black dark:text-zinc-50">
            🎁 Amigo Secreto
          </h1>
          <p className="text-lg leading-8 text-zinc-600 dark:text-zinc-400">
            Añade a los participantes, realiza el sorteo y cada persona
            recibirá por correo su asignación — de forma exclusiva y secreta.
          </p>
        </header>

        <Organizador />
      </main>
    </div>
  );
}

